impl CrawlEngineHandle {
    #[frb]
    pub fn crawl_stream(&self, req: CrawlStreamRequest, sink: crate::frb_generated::StreamSink<CrawlEvent>) {
        use futures_util::StreamExt;
        use std::sync::OnceLock;
        static FRB_STREAM_TOKIO_RT: OnceLock<tokio::runtime::Runtime> = OnceLock::new();
        let _rt = FRB_STREAM_TOKIO_RT.get_or_init(|| {
            tokio::runtime::Builder::new_multi_thread()
                .enable_all()
                .build()
                .expect("failed to build tokio runtime for FRB streaming")
        });
        let inner = self.inner.clone();
        let core_req: crawlberg::CrawlStreamRequest = req.into();
        _rt.spawn(async move {
            match inner.crawl_stream(core_req).await {
                Ok(mut stream) => {
                    while let Some(item) = stream.next().await {
                        match item {
                            Ok(chunk) => {
                                let _ = sink.add(CrawlEvent::from(chunk));
                            }
                            Err(e) => {
                                let _ = sink.add_error(e.to_string());
                                break;
                            }
                        }
                    }
                }
                Err(e) => {
                    let _ = sink.add_error(e.to_string());
                }
            }
        });
    }
    #[frb]
    pub fn batch_crawl_stream(&self, req: BatchCrawlStreamRequest, sink: crate::frb_generated::StreamSink<CrawlEvent>) {
        use futures_util::StreamExt;
        use std::sync::OnceLock;
        static FRB_STREAM_TOKIO_RT: OnceLock<tokio::runtime::Runtime> = OnceLock::new();
        let _rt = FRB_STREAM_TOKIO_RT.get_or_init(|| {
            tokio::runtime::Builder::new_multi_thread()
                .enable_all()
                .build()
                .expect("failed to build tokio runtime for FRB streaming")
        });
        let inner = self.inner.clone();
        let core_req: crawlberg::BatchCrawlStreamRequest = req.into();
        _rt.spawn(async move {
            match inner.batch_crawl_stream(core_req).await {
                Ok(mut stream) => {
                    while let Some(item) = stream.next().await {
                        match item {
                            Ok(chunk) => {
                                let _ = sink.add(CrawlEvent::from(chunk));
                            }
                            Err(e) => {
                                let _ = sink.add_error(e.to_string());
                                break;
                            }
                        }
                    }
                }
                Err(e) => {
                    let _ = sink.add_error(e.to_string());
                }
            }
        });
    }
}

/// When to use the headless browser fallback.
#[frb(mirror(BrowserMode), unignore)]
pub enum BrowserMode {
    /// Automatically detect when JS rendering is needed and fall back to browser.
    Auto,
    /// Always use the browser for every request.
    Always,
    /// Never use the browser fallback.
    Never,
    /// Always use the browser with all stealth surfaces enabled.
    ///
    /// Behaves like [`Always`](BrowserMode::Always) for escalation purposes
    /// (every request is routed through the browser tier), but additionally
    /// enables:
    ///
    /// - browser JavaScript stealth patches
    /// - native-backend TLS fingerprint spoofing
    /// - stealth-aware default user-agent when no explicit UA is set
    /// - 1920×1080 viewport override
    ///
    /// Use this instead of setting the now-removed `BrowserConfig.stealth`
    /// boolean field.
    Stealth,
}

/// Wait strategy for browser page rendering.
#[frb(mirror(BrowserWait), unignore)]
pub enum BrowserWait {
    /// Wait until network activity is idle.
    NetworkIdle,
    /// Wait for a specific CSS selector to appear in the DOM.
    Selector,
    /// Wait for a fixed duration after navigation.
    Fixed,
}

/// Browser backend used for JavaScript rendering.
